"""Hippie Station Cargo's front (office, lobby, quartermaster, supply checkpoint), generated by the node graph
(forge/proc), the sixth department.

    python tools/mapforge/blueprints/cargo_v1.py            # run the graph, one picture per node
    python tools/mapforge/mapforge.py build blueprints/cargo_v1.py
    MAPFORGE_SEED=3 python tools/mapforge/mapforge.py build blueprints/cargo_v1.py

The bay (conveyors, the shuttle dock, the MULE beacons), the sorting room's chutes, the warehouse and the mining dock are
cores and stay as they are. What the outline fixes: every door and window on the zone's edge (the bay door, the two
sorting doors, the lobby's open front onto the hallway, the QM's doors to the bay and the dock, the checkpoint's door).
The office block is cut per seed at the counter: staff behind it on the bay side, the public lobby on the hallway side.
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, ".."))
from forge import dmm  # noqa: E402
from forge.proc import geo as G  # noqa: E402
from forge.proc import shell, furnish, emit, solve  # noqa: E402
from assets import cargo as assets  # noqa: E402
from forge.proc.shell import X, door, keep  # noqa: E402

NAME = "cargo_v1"
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
BASE_MAP = os.path.join(ROOT, "_maps", "map_files", "HippieStation", "hippiestation.dmm")
BBOX = (77, 109, 96, 125)
OFFICE, QM, CHECK = "/area/quartermaster/office", "/area/quartermaster/qm", "/area/security/checkpoint/supply"
AREAS = (OFFICE, QM, CHECK)


def in_zone(a):
    return a in AREAS


# ---------------------------------------------------------------- inputs: what the outline fixes
FRONT = [(95, 118), (95, 119)]          # the lobby's open front onto the hallway
QM_DOORS = [(81, 114), (85, 112)]       # to the bay, to the mining dock
CHECK_DOOR = (90, 112)                  # to the mining dock
LOOKOUT = [(91, 115), (92, 115), (93, 115)]     # the checkpoint's window into the lobby


def edge_glass():
    """Windows on the zone's edge that look out onto somewhere (kept as they are)."""
    m = dmm.read(BASE_MAP)
    x0, y0, x1, y1 = BBOX
    zone = {(x, y) for x in range(x0, x1 + 1) for y in range(y0, y1 + 1)
            if m.get(x, y) is not None and in_zone(m.get(x, y).apath)}
    out = []
    for p in sorted(zone):
        t = m.get(*p)
        if not t.has("/obj/effect/spawner/structure/window") or t.has("/obj/machinery/door"):
            continue
        for dx, dy in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            q = (p[0] + dx, p[1] + dy)
            u = m.get(*q)
            if q not in zone and u is not None and not u.tpath.startswith("/turf/closed"):
                out.append(p)
                break
    return out


GLASS = edge_glass()
GATES = FRONT + QM_DOORS + [CHECK_DOOR]

PARAMS = dict(seed=1)
FLOOR = "/turf/open/floor/plasteel"
ROOM_TABLE = {
    "office": dict(area=OFFICE, floor=FLOOR, name="Cargo Office", label="OFFICE"),
    "lobby": dict(area=OFFICE, floor=FLOOR, name="Cargo Lobby", label="LOBBY", newscaster=True),
    "qm": dict(area=QM, floor=FLOOR, name="Quartermaster's Office", label="QM"),
    "checkpoint": dict(area=CHECK, floor="/turf/open/floor/plasteel/dark", name="Supply Security Post",
                       label="CHECKPOINT"),
}

OBLOCK = (85, 116, 94, 121)     # the office and the lobby, cut at the counter


def authored(P):
    return {"O": X((5, "office"), (1.0, "lobby"))}


def plans(P, fill=None):
    f = fill or authored(P)
    return [
        (OBLOCK, f["O"]),
        ((85, 115, 89, 115), "office"),         # the office's south row
        ((85, 122, 87, 123), "office"),         # the nook up to the sorting door
        ((85, 124, 86, 124), "office"),
        ((79, 111, 84, 113), "qm"),
        ((91, 111, 94, 114), "checkpoint"),
    ]


def program(P):
    """One block. The office fronts the bay door on the west, the lobby the hallway on the east."""
    blocks = [solve.Block("O", OBLOCK, {"w": ("bay", 116, 121), "e": ("hall", 116, 121)})]
    W = solve.Want
    wants = [
        W("office", 30, min=(4, 6), front=("bay",)),
        W("lobby", 24, min=(3, 6), front=("hall",)),
    ]
    return blocks, wants


LINK_PAIRS = [("office", "lobby")]


def seeded(seed, tries=8):
    last = None
    for t in range(tries):
        P = dict(PARAMS)
        blocks, wants = program(P)
        trees, rects, report = solve.solve(blocks, wants, LINK_PAIRS, seed="%s.%d" % (seed, t), ratio=(0.2, 5.0),
                                           fill=True, fixed={"office": "O", "lobby": "O"})
        if trees is None:
            break
        g = graph(fill=trees)
        geo = g.run()
        geo.notes[:0] = report + ["seed %s: try %d, %d problems" % (seed, t, len(geo.problems))]
        last = (g, geo)
        if not geo.problems:
            break
    return last


LINKS = [keep(p, "lobby") for p in FRONT] + [keep(p, "qm") for p in QM_DOORS] + [
    keep(CHECK_DOOR, "checkpoint"),
    door("office", "lobby", at=0.75, type="windoor", name="Cargo Desk", access="50"),
    door("office", "lobby", at=0.25, name="Cargo Office", kind="mining", glass=True, access="50"),
]


SEED = int(os.environ.get("MAPFORGE_SEED", "1"))
if SEED != 1:
    PARAMS["seed"] = SEED
    NAME += "_s%d" % SEED


def graph(fill=None, **over):
    P = dict(PARAMS)
    P.update(over)
    g = G.Graph(NAME, **P)
    g.add("outline", shell.outline, view="kind", base=BASE_MAP, bbox=BBOX, in_zone=in_zone,
          keep=GLASS + LOOKOUT, gates=GATES)
    g.add("slice", shell.slice_rooms, view="rooms", plans=plans(P, fill), rooms=ROOM_TABLE)
    g.add("tidy", shell.tidy, view="rooms")
    g.add("openings", shell.openings, view="rooms", links=LINKS)
    g.add("fields", shell.fields, view="fields")
    g.add("furnish", furnish.furnish, view="items", assets=assets.ASSETS)
    return g


_graph, _geo = seeded(SEED) if SEED != 1 else (graph(), None)
_geo = _geo or _graph.run()
globals().update(emit.blueprint(_geo, NAME, extra=dict(STYLE="meta", DISPOSALS="route", DRESS_HALL_FRONT=True,
                                                       BASE=BASE_MAP)))


def main():
    g, geo = _graph, _geo
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = g.pictures(out, tile=20)
    G.sheet(paths, os.path.join(out, NAME + "_nodes.png"), cols=3)
    G.draw(geo, "items", os.path.join(out, NAME + "_furnish_big.png"), tile=30, title="furnish")
    for n in geo.notes:
        print(n)
    for p in geo.problems:
        print("PROBLEM", p)
    print("pictures:", os.path.relpath(os.path.join(out, NAME + "_nodes.png"), ROOT))


if __name__ == "__main__":
    main()
